func (c *Client) findPageByTitle(ctx context.Context, baseURL, spaceKey, title, authHeader string) (*PageContentItem, error) {
	queryURL := fmt.Sprintf("%s/wiki/rest/api/content?spaceKey=%s&title=%s&expand=version,body.storage",
		baseURL, url.QueryEscape(spaceKey), url.QueryEscape(title))

	resp, err := c.doWithRetry(ctx, authHeader, func() (*http.Request, error) {
		return http.NewRequestWithContext(ctx, http.MethodGet, queryURL, nil)
	})
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	respBytes, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		bodyText := strings.TrimSpace(string(respBytes))
		if bodyText != "" {
			return nil, fmt.Errorf("search content returned status %d: %s", resp.StatusCode, bodyText)
		}
		return nil, fmt.Errorf("search content returned status %d", resp.StatusCode)
	}

